"""MAX official HMAC/replay and shared-session integration; synthetic platform proofs only."""
import hashlib,hmac,json,secrets,subprocess,time,urllib.parse,requests
import test_support_archive as support
class MaxIdentity(support.SupportArchive):
 @classmethod
 def setUpClass(cls):
  super().setUpClass()
  for op in ['publication','maxapp']:
   r=subprocess.run([cls.f.php,str(cls.f.path/('scripts/migrate-'+op+'.php')),'up'],capture_output=True,text=True)
   if r.returncode:raise RuntimeError(r.stderr)
 def setUp(self):
  for table in ['nd_max_account_events','nd_max_sessions','nd_max_launches','nd_max_account_links']:self.f.sql('DELETE FROM '+table)
  super().setUp();self.bot_token='SYNTHETIC_ONLY_MAX_TOKEN_0123456789abcdefghijklmnop'
 def signed(self,uid=1234567,at=None):
  p={'auth_date':str(at or int(time.time())),'query_id':secrets.token_hex(12),'user':json.dumps({'id':uid,'first_name':'SYNTHETIC + Юзер'},ensure_ascii=False,separators=(',',':'))};secret=hmac.new(b'WebAppData',self.bot_token.encode(),hashlib.sha256).digest();p['hash']=hmac.new(secret,'\n'.join(k+'='+v for k,v in sorted(p.items())).encode(),hashlib.sha256).hexdigest();return '&'.join(urllib.parse.quote(k,safe='')+'='+urllib.parse.quote(v,safe='') for k,v in p.items())
 def app(self,route,d=None,s=None):
  s=s or requests.Session();url=self.base+'/max-api.php?r='+route
  return s.get(url) if d is None else s.post(url,json=d)
 def enable(self):
  self.f.php_eval('require $v["root"]."/private/app.php";require $v["root"]."/private/notifications/max.php";max_write(["token"=>$v["token"]]);',{'root':str(self.f.path),'token':self.bot_token});self.setup_action('max-miniapp',enabled=True,platform_configured=True,policy_hash=self.settings()['policy']['hash'],confirm=True)
 def paid_account(self):
  oid,items,docs=self.prepared();self.must(self.bank(items[0]));s=requests.Session();d=s.get(self.base+'/customer-api.php?r=session').json();s.headers['X-CSRF-Token']=d['csrf'];r=s.post(self.base+'/customer-api.php?r=invite',json={'token':self.token(),'password':'SYNTHETIC-max12345','password_confirmation':'SYNTHETIC-max12345','consent':True,'policy_version':self.policy['version']});self.assertEqual(r.status_code,200,r.text);r=s.post(self.base+'/customer-api.php?r=login',json={'email':self.invite_email,'password':'SYNTHETIC-max12345'});self.assertEqual(r.status_code,200,r.text);s.headers['X-CSRF-Token']=r.json()['csrf'];self.enable();return oid,s
 def test_signed_launch_link_cookie_independent_orders_replay_and_unlink(self):
  oid,website=self.paid_account();raw=self.signed();bootstrap=self.app('bootstrap',{'init_data':raw});self.assertEqual(bootstrap.status_code,200,bootstrap.text);nonce=bootstrap.json()['nonce'];self.assertFalse(bootstrap.json()['linked']);d={'init_data':raw,'nonce':nonce,'email':self.invite_email,'password':'SYNTHETIC-max12345','confirm_link':True,'consent':True,'policy_version':self.policy['version']};self.assertEqual(self.app('link',{**d,'password':'wrong'}).status_code,401);self.assertEqual(self.app('link',{**d,'confirm_link':False}).status_code,422);r=self.app('link',d);self.assertEqual(r.status_code,200,r.text);token=r.json()['session_token'];self.assertNotIn(token,json.dumps(self.f.sql('SELECT * FROM nd_max_sessions')));bearer=requests.Session();bearer.headers.update({'X-Neuro-Max-Session':token,'X-CSRF-Token':r.json()['csrf']});r=bearer.get(self.base+'/customer-api.php?r=portal/orders');self.assertEqual(r.status_code,200,r.text);self.assertIn(oid,[int(o['id']) for o in r.json()['items']]);self.assertEqual(len(bearer.cookies),0);self.assertEqual(self.app('link',d).status_code,409);self.assertEqual(self.app('bootstrap',{'init_data':raw}).status_code,409)
  self.assertEqual(self.app('resume',{'init_data':self.signed(uid=99999)},bearer).status_code,401);self.assertEqual(self.app('resume',{'init_data':self.signed()},bearer).status_code,200);self.assertEqual(bearer.get(self.base+'/lifecycle-api.php?r=flow/orders/'+str(oid)).status_code,200)
  fresh=self.signed();b=self.app('bootstrap',{'init_data':fresh}).json();self.assertTrue(b['linked']);new=self.app('login',{'init_data':fresh,'nonce':b['nonce']});self.assertEqual(new.status_code,200,new.text);self.assertEqual(self.app('unlink',{'password':'wrong'},bearer).status_code,401);self.assertEqual(self.app('unlink',{'password':'SYNTHETIC-max12345'},website).status_code,200);self.assertEqual(bearer.get(self.base+'/customer-api.php?r=portal/orders').status_code,401);self.assertEqual(website.get(self.base+'/customer-api.php?r=portal/orders').status_code,200);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_max_account_links')[0]['n'],0)
 def test_invalid_proofs_never_create_launches_and_flag_does_not_weaken_website(self):
  oid,website=self.paid_account();raw=self.signed();invalid=[raw+'&hash='+'0'*64,raw+'&user=%7B%22id%22%3A99%7D',raw.replace('SYNTHETIC','TAMPERED'),self.signed(at=int(time.time())-301),self.signed(at=int(time.time())+60),raw+'&x=%GG'];before=self.f.sql('SELECT COUNT(*) n FROM nd_customer_accounts')[0]['n']
  for value in invalid:self.assertEqual(self.app('bootstrap',{'init_data':value}).status_code,401)
  self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_max_launches')[0]['n'],0);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_customer_accounts')[0]['n'],before);self.assertFalse(self.app('settings').json()['public_registration']);self.setup_action('max-miniapp',enabled=False,confirm=True);self.assertFalse(self.app('settings').json()['enabled']);self.assertEqual(self.app('bootstrap',{'init_data':raw}).status_code,503);self.assertEqual(website.get(self.base+'/customer-api.php?r=portal/orders').status_code,200);self.assertEqual(requests.get(self.base+'/').headers.get('X-Frame-Options'),'DENY');maxpage=requests.get(self.base+'/max.php');self.assertNotIn('X-Frame-Options',maxpage.headers);self.assertIn('frame-ancestors https://max.ru https://web.max.ru',maxpage.headers['Content-Security-Policy']);self.assertNotIn("'unsafe-inline'",maxpage.headers['Content-Security-Policy'])
 def test_unpaid_existing_account_cannot_link(self):
  self.prepare_synthetic_owner();self.setup_action('open',confirm=True);email='unpaid-'+secrets.token_hex(6)+'@example.invalid';c=self.must(self.owner.post(self.base+'/api.php?r=crm/customers',json={'name':'SYNTHETIC unpaid identity','email':email,'request_key':secrets.token_hex(32)}))['record'];self.f.php_eval('require $v["root"]."/private/app.php";$q=db()->prepare("INSERT INTO nd_customer_accounts(customer_id,email,password_hash,status) VALUES (?,?,?,\'active\')");$q->execute([$v["customer"],$v["email"],password_hash("SYNTHETIC-unpaid12345",PASSWORD_DEFAULT)]);$id=db()->lastInsertId();db()->prepare("INSERT INTO nd_customer_auth(account_id,registration_method,email_verified_at,consent_at,policy_version,policy_hash) VALUES (?,\'invitation\',?,0,\'\',\'\')")->execute([$id,time()]);',{'root':str(self.f.path),'customer':int(c['id']),'email':email});self.enable();raw=self.signed();b=self.app('bootstrap',{'init_data':raw}).json();r=self.app('link',{'init_data':raw,'nonce':b['nonce'],'email':email,'password':'SYNTHETIC-unpaid12345','confirm_link':True,'consent':True,'policy_version':self.settings()['policy']['version']});self.assertEqual(r.status_code,409,r.text);self.assertEqual(r.json()['error_code'],'payment_required');self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_max_account_links')[0]['n'],0)

for name in dir(support.SupportArchive):
 if name.startswith('test_'):setattr(MaxIdentity,name,None)
